const rawResponses = $('Confluence Seiten laden').all();
const existingItems = $('Bestehende Seiten laden').all();
const cfg = $('Config').first().json;
const spaceKey = String(cfg.spaceKey || '');
const maxDeletePercent = Number(cfg.deleteSafetyMaxPercent ?? 35);
const minExistingForPercentGuard = Number(cfg.deleteSafetyMinExisting ?? 20);

const currentIds = new Set();
for (const item of rawResponses) {
  const r = item.json || {};
  if (Array.isArray(r.results)) {
    for (const p of r.results) {
      if (p?.id) currentIds.add(String(p.id));
    }
  } else if (r.id) {
    currentIds.add(String(r.id));
  }
}

const existingRows = [];
for (const item of existingItems) {
  const value = item.json;
  const rows = Array.isArray(value) ? value : [value];
  for (const row of rows) {
    if (!row?.id || !row?.page_id) continue;
    if (spaceKey && String(row.space_key || '') !== spaceKey) continue;
    existingRows.push(row);
  }
}

if (existingRows.length > 0 && currentIds.size === 0) {
  throw new Error(
    'DELETE_GUARD_CURRENT_CONFLUENCE_EMPTY: Supabase hat ' +
    existingRows.length + ' Seiten im Space ' + spaceKey +
    ', der aktuelle Confluence-Abruf aber 0. Keine Loeschung ausgefuehrt.'
  );
}

const deletedPages = existingRows
  .filter(row => !currentIds.has(String(row.page_id)))
  .map(row => ({
    source_id: String(row.id),
    page_id: String(row.page_id),
    title: row.title || 'Ohne Titel',
    space_key: row.space_key || spaceKey
  }));

const deletePercent = existingRows.length > 0
  ? (deletedPages.length / existingRows.length) * 100
  : 0;

if (
  existingRows.length >= minExistingForPercentGuard &&
  deletedPages.length > 0 &&
  deletePercent > maxDeletePercent
) {
  throw new Error(
    'DELETE_GUARD_TOO_MANY_MISSING_PAGES: ' +
    deletedPages.length + ' von ' + existingRows.length +
    ' Seiten fehlen (' + deletePercent.toFixed(1) + '%). ' +
    'Grenze=' + maxDeletePercent + '%. Keine Loeschung ausgefuehrt.'
  );
}

return [{
  json: {
    has_deleted_pages: deletedPages.length > 0,
    deleted_count: deletedPages.length,
    deleted_pages: deletedPages,
    deleted_source_ids: deletedPages.map(p => p.source_id),
    deleted_page_ids: deletedPages.map(p => p.page_id),
    confluence_pages_current: currentIds.size,
    supabase_pages_existing: existingRows.length,
    delete_percent: Math.round(deletePercent * 10) / 10,
    space_key: spaceKey
  }
}];

const crypto = require('crypto');
const responses = $('Confluence Seiten laden').all();
const spaceKey = $('Config').first().json.spaceKey;
const BASE = 'https://rwg-r.atlassian.net/wiki';

const pages = [];

for (const item of responses) {
  const response = item.json || {};

  if (Array.isArray(response.results)) {
    for (const page of response.results) {
      pages.push(page);
    }
  } else if (response.id && response.title) {
    pages.push(response);
  }
}

const ENTS = {
