  le: '≤',
  ge: '≥',
  micro: 'µ',
  permil: '‰',
  dagger: '†',
  hearts: '♥'
};

function decodeEntities(input) {
  let text = String(input ?? '');

  text = text.replace(/&#(\d+);/g, (match, decimalValue) => {
    const code = parseInt(decimalValue, 10);

    return Number.isFinite(code)
      ? String.fromCodePoint(code)
      : match;
  });

  text = text.replace(/&#[xX]([0-9a-fA-F]+);/g, (match, hexValue) => {
    const code = parseInt(hexValue, 16);

    return Number.isFinite(code)
      ? String.fromCodePoint(code)
      : match;
  });

  text = text.replace(
    /&([a-zA-Z][a-zA-Z0-9]*);/g,
    (match, name) => {
      return Object.prototype.hasOwnProperty.call(ENTS, name)
        ? ENTS[name]
        : match;
    }
  );

  return text;
}

function extractAttribute(tag, attributeName) {
  const escapedName = attributeName.replace(
    /[.*+?^${}()|[\]\\]/g,
    '\\$&'
  );

  const match = String(tag).match(
    new RegExp(
      escapedName + '\\s*=\\s*(["\'])(.*?)\\1',
      'i'
    )
  );

  return match
    ? decodeEntities(match[2])
    : '';
}

function unwrapConfluenceStorage(storage) {
  let text = String(storage ?? '');

  // Kommentare, JavaScript und CSS vollständig entfernen.
  text = text.replace(/<!--[\s\S]*?-->/g, ' ');
  text = text.replace(
    /<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi,
    ' '
  );

  /*
   * Inhalt von Confluence-Codeblöcken erhalten.
   *
   * Wichtig:
   * Die CDATA-Inhalte sind der eigentliche Code.
   * Die umgebenden Makroparameter wie language, theme,
   * linenumbers, width oder collapse dürfen nicht in den
   * RAG-Text gelangen.
   */
  text = text.replace(
    /<ac:plain-text-body\b[^>]*>\s*<!\[CDATA\[([\s\S]*?)\]\]>\s*<\/ac:plain-text-body>/gi,
    '\n$1\n'
  );

  text = text.replace(
    /<ac:plain-text-link-body\b[^>]*>\s*<!\[CDATA\[([\s\S]*?)\]\]>\s*<\/ac:plain-text-link-body>/gi,
    '$1'
  );

  /*
   * Rich-Text-Inhalt erhalten.
   * Es wird nur der Confluence-Wrapper entfernt.
   */
  text = text.replace(
    /<\/?ac:rich-text-body\b[^>]*>/gi,
    '\n'
  );

  /*
   * Confluence-Makroparameter vollständig entfernen.
   *
   * Genau aus diesen Parametern entstanden bisher Texte wie:
   *
   * none
   * text wide 760 true
   * wide 760
   */
  text = text.replace(
    /<ac:parameter\b[^>]*>[\s\S]*?<\/ac:parameter>/gi,
    ' '
  );

  text = text.replace(
    /<ac:placeholder\b[^>]*>[\s\S]*?<\/ac:placeholder>/gi,
    ' '
  );

  text = text.replace(
    /<ac:adf-extension\b[^>]*>[\s\S]*?<\/ac:adf-extension>/gi,
    ' '
  );

  /*
   * Anhänge als verständliche Textreferenz erhalten.
   */
  text = text.replace(
    /<ri:attachment\b[^>]*\/?>/gi,
    tag => {
      const filename = extractAttribute(tag, 'ri:filename');

      return filename
        ? ` [Anhang: ${filename}] `
        : ' ';
    }
  );

  /*
   * Verlinkte Confluence-Seiten mit ihrem Titel erhalten.
   */
  text = text.replace(
    /<ri:page\b[^>]*\/?>/gi,
    tag => {
      const title = extractAttribute(
        tag,
        'ri:content-title'
      );

      return title
        ? ` ${title} `
        : ' ';
    }
  );

  /*
   * URLs aus Confluence-Ressourcen erhalten.
   */
  text = text.replace(
    /<ri:url\b[^>]*\/?>/gi,
    tag => {
      const value = extractAttribute(
        tag,
        'ri:value'
      );

      return value
        ? ` ${value} `
        : ' ';
    }
  );

  /*
   * Alle übrigen ac:- und ri:-Elemente entfernen.
   * Sie enthalten keine eigenständigen fachlichen Inhalte.
   */
  text = text.replace(
    /<\/?(?:ac|ri):[^>]+>/gi,
    ' '
  );

  return text;
}

function dedupeAdjacentBlocks(input) {
  const blocks = String(input ?? '')
    .split(/\n{2,}/)
    .map(block => block.trim())
    .filter(Boolean);

  const output = [];
  let previousKey = null;

  for (const block of blocks) {
    const key = block
      .replace(/\s+/g, ' ')
      .trim()
      .toLocaleLowerCase('de-DE');

    // Direkt aufeinanderfolgende identische Textblöcke entfernen.
    if (key && key === previousKey) {
      continue;
    }

    output.push(block);
    previousKey = key;
  }

  return output.join('\n\n');
}

function cleanParserArtifacts(input) {
  let text = String(input ?? '');

  /*
   * Bekannte Confluence-Layoutartefakte entfernen:
   *
   * text wide 760 true
   * wide 760
   * wide 880 false
   */
  text = text.replace(
    /\b(?:text\s+)?wide\s+\d+(?:\s+(?:true|false))?\b/gi,
    ' '
  );

  /*
   * Führende Platzhalter entfernen:
   *
   * none Dokumentation
   * null Dokumentation
   * undefined Dokumentation
   */
  text = text.replace(
    /^\s*(?:none|null|undefined)\s+(?=\S)/i,
    ''
  );

  text = text.replace(
    /(^|\n)\s*(?:none|null|undefined)\s+(?=\S)/gi,
    '$1'
  );

  /*
   * Confluence-UI-Texte entfernen.
   */
  text = text.replace(
    /(^|\n)\s*(?:Weitere Zeilen anzeigen|Show more lines)\s*(?=\n|$)/gi,
    '$1'
  );

  /*
   * Einzelne Markdown-Codeblockreste entfernen.
   */
  text = text.replace(
    /(^|\n)\s*``+\s*(?=\n|$)/g,
    '$1'
  );

  /*
   * Unsichtbare Unicode-Zeichen entfernen.
   */
  text = text
    .replace(/[\u200B-\u200D\u2060\uFEFF]/g, '')
    .replace(/[\u00A0\u202F]/g, ' ')
    .replace(/\r\n?/g, '\n');

  /*
   * Leerzeichen und Zeilenumbrüche vereinheitlichen.
   */
  text = text
    .replace(/[ \t]+\n/g, '\n')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  return dedupeAdjacentBlocks(text);
}

function htmlToText(storage) {
  if (!storage) {
    return '';
  }

  let text = unwrapConfluenceStorage(storage);

  /*
   * Tabellen lesbar machen.
   */
  text = text.replace(
    /<\/(td|th)>/gi,
    '\t'
  );

  text = text.replace(
    /<\/tr>/gi,
    '\n'
  );

  /*
   * Blockelemente in Zeilenumbrüche umwandeln.
   */
  text = text.replace(
    /<\/(p|div|h[1-6]|blockquote|pre|table|ul|ol)>/gi,
    '\n'
  );

  text = text.replace(
    /<li\b[^>]*>/gi,
    '- '
  );

  text = text.replace(
    /<\/li>/gi,
    '\n'
  );

  text = text.replace(
    /<br\s*\/?>/gi,
    '\n'
  );

  /*
   * Verbleibende HTML-Tags entfernen.
   */
  text = text.replace(
    /<[^>]+>/g,
    ' '
  );

  /*
   * Confluence liefert Inhalte teilweise mehrfach escaped.
   */
  text = decodeEntities(text);
  text = decodeEntities(text);

  return cleanParserArtifacts(text);
}

function assertCleanContent(pageId, title, contentText) {
  const checks = [
    {
      code: 'WIDE_LAYOUT_ARTIFACT',
      regex: /\b(?:text\s+)?wide\s+\d+(?:\s+(?:true|false))?\b/i
    },
    {
      code: 'LEADING_NONE_ARTIFACT',
      regex: /^\s*(?:none|null|undefined)\b/i
    },
    {
      code: 'CONFLUENCE_PARAMETER_ARTIFACT',
      regex: /<\/?ac:(?:parameter|plain-text-body|rich-text-body|structured-macro)\b/i
    }
  ];

  for (const check of checks) {
    if (check.regex.test(contentText)) {
      throw new Error(
        'CONFLUENCE_TEXT_CLEANUP_FAILED: ' +
        check.code +
        ', page_id=' +
        pageId +
        ', title=' +
        title
      );
    }
  }
}

const seen = new Set();
const output = [];

for (const page of pages) {
  const pageId = String(page.id);

  if (seen.has(pageId)) {
    continue;
  }

  seen.add(pageId);

  const title = cleanParserArtifacts(
    decodeEntities(page.title || 'Ohne Titel')
  );

  const contentText = htmlToText(
    page.body?.storage?.value || ''
  );

  const webui = page._links?.webui || '';

  const labels = (
    page.metadata?.labels?.results || []
  )
    .map(label =>
      cleanParserArtifacts(
        decodeEntities(label?.name || '')
      )
    )
    .filter(Boolean);

  /*
   * Sicherheitsprüfung:
   * Fehlerhafte Texte dürfen nicht weiter zum Chunking gelangen.
   */
  assertCleanContent(
    pageId,
    title,
    contentText
  );

  /*
   * Der Hash muss aus dem bereinigten Text entstehen.
   *
   * Dadurch werden bereits importierte Seiten als geändert
   * erkannt und mit bereinigten Chunks neu aufgebaut.
   */
  const contentHash = crypto
    .createHash('sha256')
    .update(
      title + '\n' + contentText,
      'utf8'
    )
    .digest('hex');

  output.push({
    json: {
      page_id: pageId,
      title,
      space_key: spaceKey,
      page_url: webui
        ? BASE + webui
        : BASE,
      content_text: contentText,
      content_hash: contentHash,
      version_number: page.version?.number ?? null,
      labels,
      confluence_created_at:
        page.history?.createdDate ?? null,
      confluence_modified_at:
        page.version?.when ?? null,
      parser_version:
        'confluence-storage-clean-v1',
      content_is_empty:
        contentText.length === 0
    }
  });
}

if (output.length === 0) {
  return [
    {
      json: {
        _no_confluence_pages: true,
        space_key: spaceKey
      }
    }
  ];
}

return output;

const neuAlle = $('Seiten normalisieren')
  .all()
  .filter(i => i.json && i.json.page_id);
const bestehendeItems = $('Bestehende Seiten laden').all();

const bekannt = new Map();
for (const it of bestehendeItems) {
  const value = it.json;
  const rows = Array.isArray(value) ? value : [value];
  for (const r of rows) {
    if (r && r.page_id) {
      bekannt.set(String(r.page_id), r);
    }
  }
}

if (neuAlle.length === 0) {
  return [{ json: { _no_confluence_pages: true } }];
}

const out = [];
for (const it of neuAlle) {
  const neu = it.json;
  const existing = bekannt.get(String(neu.page_id)) || null;
  const unchanged = !!existing && existing.content_hash === neu.content_hash;

  out.push({
    json: {
      ...neu,
      unchanged,
      existing_id: existing?.id ?? null,
      existing_content_hash: existing?.content_hash ?? null,
      existing_audience: existing?.audience ?? null,
      existing_ingested_at: existing?.ingested_at ?? null,
      existing_last_ingested_at: existing?.last_ingested_at ?? null,
      existing_ingestion_version: existing?.ingestion_version ?? 0
    }
  });
}

return out;

const alle = $input.all().filter(i => i.json && i.json.page_id);
const geaendert = alle.filter(i => i.json.unchanged === false);
const unveraendert = alle.length - geaendert.length;

const stats = {
  seiten_gesamt: alle.length,
  seiten_geaendert: geaendert.length,
  seiten_unveraendert: unveraendert
};

if (geaendert.length === 0) {
  return [{
    json: {
      ...stats,
      no_changes: true,
      status: 'NO_CHANGES',
      message: alle.length === 0
        ? 'Keine aktuellen Confluence-Seiten gefunden.'
        : 'Keine geaenderten Confluence-Seiten gefunden.'
    }
  }];
}

return geaendert.map((it, index) => ({
  json: {
    ...it.json,
    ...stats,
    no_changes: false,
    page_position: index + 1,
    changed_total: geaendert.length
  }
}));

const changedPages = $('Geaenderte Seiten vorbereiten')
  .all()
  .map(i => i.json)
  .filter(p => p.no_changes === false);

const sourceRows = [];
for (const it of $input.all()) {
  const value = it.json;
  if (Array.isArray(value)) sourceRows.push(...value);
  else if (value) sourceRows.push(value);
}

const ALLOWED_AUDIENCES = ['public', 'it_internal'];

const out = [];
for (const source of sourceRows) {
  const page = changedPages.find(p => String(p.page_id) === String(source.page_id));
  if (!page) {
    throw new Error('PAGE_CONTEXT_NOT_FOUND_FOR_SOURCE: ' + String(source.page_id));
  }
  if (!source.id) {
    throw new Error('SOURCE_ID_MISSING_FOR_PAGE: ' + String(source.page_id));
  }

  const dbAudience = source.audience;
  if (!ALLOWED_AUDIENCES.includes(dbAudience)) {
    throw new Error('AUDIENCE_INVALID_OR_MISSING_FROM_DB: page=' + String(source.page_id) + ', value=' + String(dbAudience));
  }

  out.push({
    json: {
      ...page,
      source_id: source.id,
      page_audience: dbAudience
    }
  });
}

if (out.length !== changedPages.length) {
  throw new Error('SOURCE_PAGE_COUNT_MISMATCH: sources=' + out.length + ', pages=' + changedPages.length);
}

return out;

const cfg = $('Config').first().json;

const CHUNK_SIZE = Number(
  cfg.chunkSize || 1600
);

const OVERLAP = Number(
  cfg.chunkOverlap || 200
);

const BATCH_SIZE = Number(
  cfg.embeddingBatchSize || 50
);

const FLOW_VERSION = String(
  cfg.ragFlowVersion ?? ''
).trim();

const ALLOWED_AUDIENCES = [
  'public',
  'it_internal'
];

const ALLOWED_CHUNK_TYPES = [
  'header',
  'content'
];

const REQUIRED_META = [
  'source_type',
  'source_ref',
  'title',
  'url',
  'chunk_type',
  'updated_at',
  'content_hash',
  'rag_flow_version',
  'audience'
];

if (!FLOW_VERSION) {
  throw new Error(
    'CONFIG_RAG_FLOW_VERSION_MISSING: ' +
    'Config.ragFlowVersion ist leer.'
  );
}

if (
  !Number.isInteger(BATCH_SIZE) ||
  BATCH_SIZE < 1 ||
  BATCH_SIZE > 2048
) {
  throw new Error(
    'INVALID_EMBEDDING_BATCH_SIZE: ' +
    BATCH_SIZE
  );
}

if (
  !Number.isInteger(CHUNK_SIZE) ||
  CHUNK_SIZE < 200
) {
  throw new Error(
    'INVALID_CHUNK_SIZE: ' +
    CHUNK_SIZE
  );
}

if (
  !Number.isInteger(OVERLAP) ||
  OVERLAP < 0 ||
  OVERLAP >= CHUNK_SIZE
) {
  throw new Error(
    'INVALID_CHUNK_OVERLAP: ' +
    OVERLAP
  );
}

function estimateTokens(text) {
  return Math.ceil(
    String(text || '').length / 4
  );
}

function assertNoParserArtifacts(
  text,
  pageId,
  title
) {
  const checks = [
    {
      code: 'WIDE_LAYOUT_ARTIFACT',
      regex:
        /\b(?:text\s+)?wide\s+\d+(?:\s+(?:true|false))?\b/i
    },
    {
      code: 'LEADING_NONE_ARTIFACT',
      regex:
        /^\s*(?:none|null|undefined)\b/i
    },
    {
      code: 'CONFLUENCE_PARAMETER_ARTIFACT',
      regex:
        /<\/?ac:(?:parameter|plain-text-body|rich-text-body|structured-macro)\b/i
    },
    {
      code: 'SHOW_MORE_LINES_ARTIFACT',
      regex:
        /(^|\n)\s*(?:Weitere Zeilen anzeigen|Show more lines)\s*(?=\n|$)/i
    }
  ];

  for (const check of checks) {
    if (check.regex.test(text)) {
      throw new Error(
        'CHUNK_BUILD_BLOCKED_BY_PARSER_ARTIFACT: ' +
        check.code +
        ', page=' +
        pageId +
        ', title=' +
        title
      );
    }
  }
}

function hardSplit(
  input,
  size,
  overlap
) {
  const text = String(input || '');
  const parts = [];

  let start = 0;

  while (start < text.length) {
    const idealEnd = Math.min(
      start + size,
      text.length
    );

    let end = idealEnd;

    if (end < text.length) {
      const window = text.slice(
        start,
        idealEnd
      );

      const minimumPosition =
        Math.floor(size * 0.6);

      const candidates = [
        window.lastIndexOf('\n'),
        window.lastIndexOf('. '),
        window.lastIndexOf('! '),
        window.lastIndexOf('? '),
        window.lastIndexOf('; '),
        window.lastIndexOf(', '),
        window.lastIndexOf(' ')
      ].filter(
        position =>
          position > minimumPosition
      );

      if (candidates.length > 0) {
        end =
          start +
          Math.max(...candidates) +
          1;
      }
    }

    const piece = text
      .slice(start, end)
      .trim();

    if (piece) {
      parts.push(piece);
    }

    if (end >= text.length) {
      break;
    }

    start = Math.max(
      start + 1,
      end - overlap
    );
  }

  return parts;
}

function splitToChunks(
  input,
  chunkSize,
  overlap
) {
  const normalized = String(
    input || ''
  ).trim();

  if (!normalized) {
    return [];
  }

  const size = Math.max(
    200,
    Number(chunkSize) || 1600
  );

  const overlapSize = Math.min(
    Math.max(
      0,
      Number(overlap) || 0
    ),
    Math.floor(size / 2)
  );

  const pieces = [];

  /*
   * Primär anhand von Absätzen aufteilen.
   */
  for (
    const rawParagraph of
    normalized.split(/\n\n+/)
  ) {
    const paragraph =
      rawParagraph.trim();

    if (!paragraph) {
      continue;
    }

    if (paragraph.length > size) {
      pieces.push(
        ...hardSplit(
          paragraph,
          size,
          overlapSize
        )
      );
    } else {
      pieces.push(paragraph);
    }
  }

  const chunks = [];
  let current = '';

  for (const piece of pieces) {
    if (!current) {
      current = piece;
      continue;
    }

    const combined =
      current +
      '\n\n' +
      piece;

    if (combined.length <= size) {
      current = combined;
      continue;
    }

    chunks.push(
      current.trim()
    );

    const tail =
      overlapSize > 0
        ? current.slice(-overlapSize)
        : '';

    const seeded =
      tail
        ? tail + '\n\n' + piece
        : piece;

    current =
      seeded.length > size
        ? piece
        : seeded;
  }

  if (current.trim()) {
    chunks.push(
      current.trim()
    );
  }

  /*
   * Zusätzliche Absicherung gegen zu lange Chunks.
   */
  const result = [];

  for (const chunk of chunks) {
    if (chunk.length > size * 1.2) {
      result.push(
        ...hardSplit(
          chunk,
          size,
          overlapSize
        )
      );
    } else {
      result.push(chunk);
    }
  }

  return result.filter(Boolean);
}

const allBatches = [];

for (const item of $input.all()) {
  const source = item.json;

  if (!source.source_id) {
    throw new Error(
      'MISSING_SOURCE_ID: ' +
      String(source.page_id)
    );
  }

  if (!source.page_id) {
    throw new Error(
      'MISSING_PAGE_ID_FOR_SOURCE_REF'
    );
  }

  const pageAudience =
    source.page_audience;

  if (
    !ALLOWED_AUDIENCES.includes(
      pageAudience
    )
  ) {
    throw new Error(
      'AUDIENCE_INVALID_FOR_PAGE: ' +
      String(source.page_id) +
      ', value=' +
      String(pageAudience)
    );
  }

  const sourceRef =
    String(source.page_id);

  const cleanedContent =
    String(
      source.content_text || ''
    ).trim();

  /*
   * Zweite Sicherheitsebene:
   *
   * Auch wenn im Normalisierungs-Node ein Fehler entsteht,
   * dürfen keine verunreinigten Texte eingebettet werden.
   */
  assertNoParserArtifacts(
    cleanedContent,
    sourceRef,
    String(source.title || '')
  );

  const baseMetadata = {
    source_type: 'confluence',
    source_ref: sourceRef,
    title: source.title,
    url: source.page_url,
    updated_at:
      source.confluence_modified_at ||
      null,
    content_hash:
      source.content_hash,
    rag_flow_version:
      FLOW_VERSION,
    parser_version:
      source.parser_version ||
      'unknown',
    audience:
      pageAudience,
    page_id:
      sourceRef,
    page_url:
      source.page_url,
    space_key:
      source.space_key,
    version_number:
      source.version_number ?? null,
    labels:
      source.labels || [],
    created_at:
      source.confluence_created_at ||
      null
  };

  const chunks = [];
  let chunkIndex = 0;

  /*
   * Header-Chunk.
   *
   * Er sorgt dafür, dass Titel und URL auch bei einer
   * allgemeineren Vektorsuche gefunden werden.
   */
  const headerParts = [];

  headerParts.push(
    '[CONFLUENCE] ' +
    source.title
  );

  headerParts.push(
    'Space: ' +
    source.space_key
  );

  if (
    Array.isArray(source.labels) &&
    source.labels.length > 0
  ) {
    headerParts.push(
      'Labels: ' +
      source.labels.join(', ')
    );
  }

  headerParts.push(
    'URL: ' +
    source.page_url
  );

  const header =
    headerParts.join('\n');

  chunks.push({
    source_id:
      source.source_id,
    source_type:
      'confluence',
    source_ref:
      sourceRef,
    audience:
      pageAudience,
    chunk_index:
      chunkIndex++,
    chunk_text:
      header,
    token_count:
      estimateTokens(header),
    metadata: {
      ...baseMetadata,
      chunk_type: 'header'
    }
  });

  /*
   * Inhalts-Chunks.
   *
   * Bei tatsächlich leeren Confluence-Strukturseiten bleibt
   * ausschließlich der Header-Chunk bestehen.
   */
  const contentParts =
    splitToChunks(
      cleanedContent,
      CHUNK_SIZE,
      OVERLAP
    );

  for (
    const contentPart of contentParts
  ) {
    const chunkText =
      source.title +
      '\n\n' +
      contentPart;

    /*
     * Jeden einzelnen finalen Chunk noch einmal prüfen.
     */
    assertNoParserArtifacts(
      chunkText,
      sourceRef,
      String(source.title || '')
    );

    chunks.push({
      source_id:
        source.source_id,
      source_type:
        'confluence',
      source_ref:
        sourceRef,
      audience:
        pageAudience,
      chunk_index:
        chunkIndex++,
      chunk_text:
        chunkText,
      token_count:
        estimateTokens(chunkText),
      metadata: {
        ...baseMetadata,
        chunk_type: 'content',
        chunk_length:
          chunkText.length
      }
    });
  }

  if (chunks.length === 0) {
    throw new Error(
      'NO_CHUNKS_CREATED_FOR_PAGE: ' +
      source.page_id
    );
  }

  /*
   * Metadaten und Chunk-Indizes validieren.
   */
  const seenIndexes =
    new Set();

  for (const chunk of chunks) {
    const metadata =
      chunk.metadata;

    for (
      const requiredKey of REQUIRED_META
    ) {
      if (
        !(requiredKey in metadata)
      ) {
        throw new Error(
          'METADATA_CORE_FIELD_MISSING: ' +
          requiredKey +
          ', page=' +
          sourceRef
        );
      }
    }

    if (
      metadata.source_ref !==
      chunk.source_ref
    ) {
      throw new Error(
        'METADATA_SOURCE_REF_MISMATCH: page=' +
        sourceRef
      );
    }

    if (
      metadata.audience !==
      chunk.audience
    ) {
      throw new Error(
        'METADATA_AUDIENCE_MISMATCH: page=' +
        sourceRef
      );
    }

    if (
      !ALLOWED_CHUNK_TYPES.includes(
        metadata.chunk_type
      )
    ) {
      throw new Error(
        'METADATA_CHUNK_TYPE_INVALID: page=' +
        sourceRef +
        ', value=' +
        String(metadata.chunk_type)
      );
    }

    if (
      seenIndexes.has(
        chunk.chunk_index
      )
    ) {
      throw new Error(
        'DUPLICATE_CHUNK_INDEX: page=' +
        sourceRef +
        ', index=' +
        chunk.chunk_index
      );
    }

    seenIndexes.add(
      chunk.chunk_index
    );
  }

  const pageBatchCount =
    Math.ceil(
      chunks.length / BATCH_SIZE
    );

  for (
    let batchIndex = 0;
    batchIndex < pageBatchCount;
    batchIndex++
  ) {
    const batchChunks =
      chunks.slice(
        batchIndex * BATCH_SIZE,
        (batchIndex + 1) *
          BATCH_SIZE
      );

    const batchTokenEstimate =
      batchChunks.reduce(
        (sum, chunk) =>
          sum +
          Number(
            chunk.token_count || 0
          ),
        0
      );

    if (
      batchTokenEstimate >
      250000
    ) {
      throw new Error(
        'EMBEDDING_BATCH_TOKEN_GUARD: page=' +
        source.page_id +
        ', batch=' +
        batchIndex +
        ', estimated=' +
        batchTokenEstimate
      );
    }

    allBatches.push({
      json: {
        ...source,
        batch_index:
          batchIndex,
        batch_count:
          pageBatchCount,
        page_chunk_count:
          chunks.length,
        chunk_count:
          batchChunks.length,
        batch_token_estimate:
          batchTokenEstimate,
        chunks:
          batchChunks
      }
    });
  }
}

/*
 * Globalen Fortschritt ergänzen.
 */
for (
  let index = 0;
  index < allBatches.length;
  index++
) {
  allBatches[index].json.batch_position =
    index + 1;

  allBatches[index].json.batch_total =
    allBatches.length;
}

return allBatches;

const stats = $('Geaenderte Seiten vorbereiten').first().json;
const cleanup = $('Geloeschte Seiten ermitteln').first().json;
const cfg = $('Config').first().json;
const events = $input.all().map(i => i.json || {});
const pageDoneEvents = events.filter(e => e.page_completed === true);
const chunksWritten = events.reduce((sum, e) => sum + Number(e.chunks_geschrieben || 0), 0);
const batchTotal = events.reduce((max, e) => Math.max(max, Number(e.batches_global || 0)), 0);

return [{
  json: {
    ok: true,
    status: 'DONE',
    rag_flow_version: cfg.ragFlowVersion,
    confluence_seiten_aktuell: cleanup.confluence_pages_current,
    seiten_gesamt_verarbeitbar: stats.seiten_gesamt,
    seiten_verarbeitet: pageDoneEvents.length,
    seiten_uebersprungen: stats.seiten_unveraendert,
    seiten_geaendert: stats.seiten_geaendert,
    seiten_geloescht: cleanup.deleted_count,
    geloeschte_page_ids: cleanup.deleted_page_ids,
    batches_verarbeitet: events.length,
    batches_erwartet: batchTotal,
    chunks_geschrieben: chunksWritten,
    embedding_model: cfg.embeddingModel,
    dimensions: cfg.embeddingDimensions,
    fertig_um: new Date().toISOString(),
    message: 'Confluence-Ingest inklusive Loeschabgleich erfolgreich abgeschlossen.'
  }
}];

const incoming = $input.first()?.json || {};
const loopBatch = $('Embedding Batch Loop').first()?.json || {};

const batch = Array.isArray(incoming.chunks) ? incoming : loopBatch;

if (!batch || !Array.isArray(batch.chunks)) {
  throw new Error('EMBEDDING_BATCH_CHUNKS_MISSING: page=' + String(batch?.page_id ?? 'unknown') + ', batch=' + String(batch?.batch_index ?? 'unknown'));
}

if (batch.chunks.length === 0) {
  throw new Error('EMBEDDING_BATCH_CHUNKS_EMPTY: page=' + String(batch.page_id ?? 'unknown') + ', batch=' + String(batch.batch_index ?? 'unknown'));
}

for (let i = 0; i < batch.chunks.length; i++) {
  const text = batch.chunks[i]?.chunk_text;
  if (typeof text !== 'string' || text.trim().length === 0) {
    throw new Error('EMBEDDING_CHUNK_TEXT_INVALID: page=' + String(batch.page_id ?? 'unknown') + ', batch=' + String(batch.batch_index ?? 'unknown') + ', index=' + i);
  }
}

return [{ json: batch }];

const s = $input.first().json;
const cleanup = $('Geloeschte Seiten ermitteln').first().json;
const cfg = $('Config').first().json;
const hadDeletes = Number(cleanup.deleted_count || 0) > 0;

return [{
  json: {
    ok: true,
    status: hadDeletes ? 'DONE_CLEANUP_ONLY' : 'DONE_NO_CHANGES',
    rag_flow_version: cfg.ragFlowVersion,
    confluence_seiten_aktuell: cleanup.confluence_pages_current,
    seiten_gesamt_verarbeitbar: s.seiten_gesamt,
    seiten_verarbeitet: 0,
    seiten_uebersprungen: s.seiten_unveraendert,
    seiten_geaendert: 0,
    seiten_geloescht: cleanup.deleted_count,
    geloeschte_page_ids: cleanup.deleted_page_ids,
    batches_verarbeitet: 0,
    chunks_geschrieben: 0,
    embedding_model: cfg.embeddingModel,
    dimensions: cfg.embeddingDimensions,
    fertig_um: new Date().toISOString(),
    message: hadDeletes
      ? 'Keine Inhaltsaenderungen. Geloeschte Confluence-Seiten und deren Chunks wurden entfernt.'
      : 'Keine geaenderten oder geloeschten Confluence-Seiten. Run sauber beendet.'
  }
}];

const batch = $('Embedding Batch Loop').first().json;
const response = $input.first().json;
const dimensions = Number($('Config').first().json.embeddingDimensions || 1536);

const data = response?.data ?? response?.body?.data ?? null;
if (!Array.isArray(data)) {
  throw new Error('EMBEDDING_DATA_MISSING: page=' + batch.page_id + ', batch=' + batch.batch_index);
}

const ordered = [...data].sort((a, b) => Number(a.index) - Number(b.index));
if (ordered.length !== batch.chunks.length) {
  throw new Error('EMBEDDING_COUNT_MISMATCH: expected=' + batch.chunks.length + ', got=' + ordered.length);
}

const rows = batch.chunks.map((chunk, index) => {
  const embedding = ordered[index]?.embedding;
  if (!Array.isArray(embedding)) {
    throw new Error('EMBEDDING_MISSING_AT_INDEX: ' + index);
  }
  if (embedding.length !== dimensions) {
    throw new Error('EMBEDDING_DIMENSION_MISMATCH: expected=' + dimensions + ', got=' + embedding.length);
  }

  return {
    source_id: chunk.source_id,
    source_type: chunk.source_type,
    source_ref: chunk.source_ref,
    audience: chunk.audience,
    chunk_index: chunk.chunk_index,
    chunk_text: chunk.chunk_text,
    token_count: chunk.token_count,
    embedding: '[' + embedding.join(',') + ']',
    metadata: chunk.metadata
  };
});

return [{
  json: {
    ...batch,
    bulk_rows: rows
  }
}];

const batch = $('Bulk Insert Payload bauen').first().json;
const { bulk_rows, chunks, ...rest } = batch;

return [{
  json: {
    ...rest,
    is_last_batch: batch.batch_index === (batch.batch_count - 1),
    chunks_geschrieben: batch.chunk_count,
    batch_finished_at: new Date().toISOString()
  }
}];
